"""Ad-hoc verification of tests/properties/strategies.py (temporary)."""
from decimal import Decimal

from hypothesis import given, settings

from app.engine.evaluator import evaluate
from app.engine.parser import parse
from tests.properties import strategies as S


def sig_equal(a: Decimal, b: Decimal, digits: int = 10) -> bool:
    from decimal import Context, ROUND_HALF_EVEN
    ctx = Context(prec=digits, rounding=ROUND_HALF_EVEN)
    return ctx.plus(a) == ctx.plus(b)


print("== render re-exported from engine:", S.render is __import__("app.engine.parser", fromlist=["render"]).render)
print("== PROPERTY_SETTINGS max_examples:", S.PROPERTY_SETTINGS().max_examples if callable(S.PROPERTY_SETTINGS) else S.MAX_EXAMPLES)

# 1. Generate a handful of ASTs, render, evaluate, cross-check the oracle.
mismatches = []
examples = []

@settings(max_examples=200)
@given(S.asts())
def check_ast(node):
    rendered = S.render(node)
    engine_val = evaluate(node)
    ref_val = S.reference_evaluate(node)
    if not sig_equal(engine_val, ref_val):
        mismatches.append((rendered, engine_val, ref_val))
    # round-trip must parse back
    reparsed = parse(rendered)
    rt_val = evaluate(reparsed)
    if not sig_equal(rt_val, engine_val):
        mismatches.append(("ROUNDTRIP:" + rendered, engine_val, rt_val))
    if len(examples) < 8:
        examples.append((rendered, str(engine_val)))

check_ast()
print("\n== sample generated exprs (rendered -> engine result):")
for r, v in examples:
    print(f"   {r!r:40} -> {v}")
print("\n== engine/oracle + round-trip mismatches:", len(mismatches))
for m in mismatches[:10]:
    print("   MISMATCH", m)

# 2. Invalid character strategy
inv = []
@settings(max_examples=50)
@given(S.expressions_with_invalid_character())
def check_invalid_char(expr):
    from app.engine.errors import InvalidCharacterError
    try:
        parse(expr)
        inv.append(("NO ERROR", expr))
    except InvalidCharacterError:
        pass
    except Exception as e:
        # Some splices may create a syntax error before the bad char; that's ok
        # only if the bad char is genuinely absent from allowed set -> still we
        # only require that it does NOT succeed.
        pass
check_invalid_char()
print("\n== invalid-char exprs that unexpectedly parsed OK:", len(inv))
for m in inv[:10]:
    print("   ", m)

# 3. Zero divisor strategy
zd = []
@settings(max_examples=50)
@given(S.zero_divisor_expressions())
def check_zero_div(expr):
    from app.engine.errors import DivisionByZeroError
    try:
        evaluate(parse(expr))
        zd.append(("NO ERROR", expr))
    except DivisionByZeroError:
        pass
check_zero_div()
print("\n== zero-divisor exprs that did NOT raise div-by-zero:", len(zd))
for m in zd[:10]:
    print("   ", m)

# 4. Over-length strategy
ol = []
@settings(max_examples=30)
@given(S.over_length_expressions(256))
def check_over_length(expr):
    if len(expr) <= 256:
        ol.append(len(expr))
check_over_length()
print("\n== over-length exprs at/under 256:", len(ol))

print("\nALL CHECKS DONE")

